  "source_routes": [
    {
      "source_handle": "P0001",
      "paper_title": "Metalenses at visible wavelengths: past, present, perspectives",
      "chapter_ids": ["CH1", "CH2", "CH3"],
      "specific_usable_material": "该文为综述提供物理界限基准：指出单界面几何导致高 NA 下视场极小（<5 µm），且无法通过单层校正像差，确立 FOV 饱和的物理根源。在设计机制上，对比波导型与共振型相位控制，揭示离轴入射下反对称局域模导致的效率损耗。实证层面，批判将单层器件与商业复眼镜头直接比较的评估方法，提供基于 MTF 和旁瓣分析的公平性能基准，用于界定当前技术的真实能力边界。"
    },
    {
      "source_handle": "P0002",
      "paper_title": "Bandwidth bounds for wide-field-of-view dispersion-engineered achromatic metalenses",
      "chapter_ids": ["CH1", "CH2"],
      "specific_usable_material": "本文量化了色散工程金属透镜的带宽物理上限，明确“大 NA+ 宽 FOV"对带宽的双重压缩效应及高 FOV 下的饱和特性，直接支撑 CH1 关于延迟 - 带宽积的论证。其推导的理想相位模型揭示了群延迟空间分布特征，指出有限孔径下掠入射所需相位范围反而最小，为 CH2 分析不同焦点定义（如 r0=Ftan(α)）对设计策略的影响提供理论依据，解释为何特定几何配置会限制宽带性能。"
    }
  ]
}

